hl.on("hyprland.start", function()
    hl.exec_cmd(terminal)
    hl.exec_cmd("nm-applet &")
    hl.exec_cmd("waybar")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE")
    hl.exec_cmd("sleep 2 && /usr/lib/xdg-desktop-portal &")
    hl.exec_cmd("systemctl --user start xdg-desktop-portal-hyprland.service")
    hl.exec_cmd("hyprctl dispatch exec [workspace 5 silent] \"env ELECTRON_OZONE_PLATFORM_HINT=wayland discord --enable-features=WebRtcPipeWireCapturer\"")
    hl.exec_cmd("~/scripts/mic-volume.sh")
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets,pkcs11")
    hl.exec_cmd("~/scripts/battery.sh")
    hl.exec_cmd("blueman-applet")
end)

